    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        Price price = priceCalculator.calculate(
    43	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    45	            throw new HotelException(
    46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    47	        }
    48	        return store.add(request, price);
    49	    }
    50	
    51	    public Reservation find(long reservationId) {
    52	        return store.find(reservationId)
    53	                .orElseThrow(() -> new HotelException(
    54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    55	    }
    56	
    57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    58	    public synchronized Reservation confirm(long reservationId) {
    59	        Reservation reservation = find(reservationId);
    60	        if (reservation.status() != ReservationStatus.PENDING) {
    61	            throw notAllowed(reservation, "confirm");
    62	        }
    63	        reservation.confirmPayment();
    64	        store.update(reservation);
    65	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    66	        emailSender.send(
    67	                reservation.guest().email(),
    68	                "Reserva confirmada - " + HOTEL_NAME,
    69	                confirmationEmailBody(reservation, receipt));
    70	        return reservation;
    71	    }
    72	
