   124	        return "Olá, " + reservation.guest().name() + "!\n\n"
   125	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   126	                + receipt.text() + "\n"
   127	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   128	                + "Até breve!\n";
   129	    }
   130	
